) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `knowledge_base`
--

INSERT INTO `knowledge_base` (`id`, `question`, `answer`, `category`, `source`, `created_at`) VALUES
(1, 'Paano mag-sumite ng reklamo?', 'Pumunta sa Reklamo page, i-click ang I-ulat ang Hinaing, piliin ang uri ng reklamo, ilarawan ang detalye, at i-click ang Isumite.', 'general', 'system', '2026-09-07 14:58:51'),
(2, 'Ano ang mediation?', 'Ang mediation ay isang proseso kung saan nag-uusap ang magkabilang panig kasama ang isang opisyal ng barangay para maayos ang gulo nang walang demandahan.', 'general', 'system', '2026-09-07 14:58:51'),
(3, 'Paano malalaman ang status ng reklamo?', 'Makikita ang status sa iyong Dashboard o sa Reklamo list. May mga status tulad ng Bago, Pagrepaso, Mediation, at Tapos.', 'general', 'system', '2026-09-07 14:58:51'),
(4, 'Sino ang pwedeng gumamit ng system?', 'Ang system na ito ay para sa lahat ng mga residente ng Barangay San Andres.', 'general', 'system', '2026-09-07 14:58:51'),
(5, 'may I know whats the business hours?', 'Hello! Siyempre naman. Ang ating Barangay San Andres Hall ay bukas mula Lunes hanggang Biyernes, alas otso ng umaga hanggang alas singko ng hapon (8:00 AM - 5:00 PM). Sarado po kami tuwing Sabado, Linggo, at holidays. \n\nKung may kailangan po kayong i-report o lakarin kahit lagpas na sa oras na ito, pwede niyo pa rin pong gamitin ang ating Complaint Management System online para mai-record na agad ang inyong concern. \n\nMay iba pa po ba akong maitutulong sa inyo ngayong araw?', 'general', 'learned_from_chat', '2026-09-26 09:18:44'),
(6, 'whats you goal?', 'Hello there! My main goal is to help you and our fellow residents here in Barangay San Andres make your voices heard and get things done. \n\nWe live by our mission: Boses ng Mamamayan, Aksyon ng Barangay. \n\nI am here to guide you whenever you need to report community issues through our Complaint Management System, whether it is about noise disturbances, uncollected trash, road damage, or neighbor disputes. I can also help you track the progress of your complaints as they go through review, mediation, and resolution. \n\nThink of me as your friendly neighbor who is always ready to assist you in making San Andres a safer, cleaner, and more peaceful place for everyone. How can I help you today?', 'general', 'learned_from_chat', '2026-09-26 10:18:49'),
(7, 'How are you?', 'Hello! I am doing great, thank you for asking. I am always happy and ready to help out here in our community. How are you doing today? Is there anything about our Barangay San Andres services or the Complaint Management System that I can help you with?', 'general', 'learned_from_chat', '2026-09-27 08:35:11'),
(8, 'what are your categories? ', 'Magandang araw! When you are ready to file a complaint or report an issue in our neighborhood, we have a few different categories to make sure your concern goes to the right people here in Barangay San Andres. \n\nHere are the main categories you can choose from:\n\n• Peace and Order (Kapayapaan at Kaayusan): For issues like neighborhood disputes, noise complaints (tulad ng maingay na videoke late at night), or untoward incidents in your area.\n\n• Sanitation and Environment (Kalinisan at Kalikasan): For uncollected garbage, clogged drainage, illegal dumping, or stray animals.\n\n• Infrastructure and Public Works (Pampublikong Estruktura): For things like broken streetlights, damaged roads, potholes, or leaking public water pipes.\n\n• Health and Safety (Kalusugan at Kaligtasan): For concerns regarding public health hazards, blocked fire exits, or safety violations.\n\n• Others (Iba pa): If your concern does not quite fit the above, you can select this and briefly describe what is going on.\n\nJust pick the one that best matches your issue when you submit your report. Is there a specific concern you are planning to report today? I am here to help you out!', 'general', 'learned_from_chat', '2026-10-25 15:26:58');

